{
  "actions": [
    {
      "action": "Enforce expiry at the display boundary",
      "mechanism": "Suppress timestamped items when local time plus 30 seconds reaches expiry, independently of connectivity.",
      "implementation": "Check eligibility before rendering and clear visible items at that threshold. Keep explicit-until-revoked items eligible unless removed.",
      "check": "Simulate six-hour outages with clock offsets of ±30 seconds; verify no timestamped item remains visible past its actual expiry.",
      "risk": "Conservative suppression can hide announcements up to 60 seconds early."
    },
    {
      "action": "Reject stale configurations without accumulating removal records",
      "mechanism": "Complete snapshots make absence authoritative; persistent generation ordering prevents older bundles from restoring removed revisions.",
      "implementation": "Assign increasing generations; reject stale item mutations server-side. Devices accept only newer complete snapshots. Reject publication when serialized size reaches 100 KB.",
      "check": "Remove an item, apply that snapshot, reboot, then replay earlier snapshots; verify absence persists. Verify oversized publication fails.",
      "risk": "Complete snapshots impose a hard capacity limit on active announcements."
    },
    {
      "action": "Stage reconnect updates before switching the display",
      "mechanism": "Isolated staging and atomic activation prevent interrupted transfers from mixing old and new configuration states.",
      "implementation": "Expose downloading, validating, and active states. Validate completeness, IDs, revisions, flags, and size; atomically commit snapshot and generation. Continue expiry enforcement throughout.",
      "check": "Interrupt transfers and power at every transition; recovery must select one complete snapshot with its matching generation.",
      "risk": "Validation failure leaves cached content active; offline revocations remain unknown."
    },
    {
      "action": "Show freshness limits alongside offline announcements",
      "mechanism": "A persistent status distinguishes locally enforced expiry from removal information that requires a successful connection.",
      "implementation": "Show last successful synchronization time and: “Offline: expired announcements are hidden. Until-revoked announcements may remain after removal; emergency removals cannot be guaranteed.”",
      "check": "Disconnect for six hours; verify the warning remains visible, including when no announcements remain, and clears only after successful synchronization.",
      "risk": "Status text requires readable placement and must not obscure announcements."
    }
  ],
  "abstention_reason": ""
}
